import bpy,pathlib,sys,numpy as np,json
D=pathlib.Path(sys.argv[sys.argv.index('--')+1]).resolve();sys.path.insert(0,str(D));import exr_io
# Asymmetric rows and >1 values catch vertical inversion, clamping, channel swaps.
y,x=np.mgrid[:5,:7];known={'R':(x+y*.01).astype(np.float32),'G':(y+x*.02).astype(np.float32),'B':(x*.3+y*.7).astype(np.float32),'A':np.ones((5,7),np.float32)};p=D/'synthetic-input.exr';exr_io.write(p,known);a=exr_io.read(p);assert all(np.array_equal(a[k],v) for k,v in known.items())
im=bpy.data.images.load(str(p),check_existing=False);pixels=np.array(im.pixels[:],np.float32).reshape(5,7,4)[::-1];assert np.array_equal(pixels,np.stack([known[k] for k in 'RGBA'],-1));sc=bpy.context.scene;sc.render.image_settings.file_format='OPEN_EXR';sc.render.image_settings.color_mode='RGBA';sc.render.image_settings.color_depth='32';sc.render.image_settings.exr_codec='NONE';im.save_render(str(D/'synthetic-blender.exr'),scene=sc);b=exr_io.read(D/'synthetic-blender.exr');assert all(np.array_equal(b[k],v) for k,v in known.items());(D/'io-synthetic.json').write_text(json.dumps({'ownRoundtripExact':True,'BlenderPixelReadExactWithDocumentedVerticalFlip':True,'BlenderEXRWriteExact':True,'noClampAboveOne':True,'shape':[5,7]},indent=2));print('IO_PASS')
